import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import Rupiah from './rupiah';

interface OrderItem {
  id: string;
  orderDate: string;
  itemName: string;
  reference: string;
  price: number;
  quantity: number;
}

interface WizardData {
  cashierName: string;
  customerName: string;
  arrival: string;
  departure: string;
  invoice: string;
  serviceType: string;
  paymentMethod: string;
  downPayment: number;
  items: OrderItem[];
}

interface PDFGeneratorOptions {
  data: WizardData;
  calculateTotal: (data: WizardData) => string;
  calculateBalance: (data: WizardData) => string;
}

// Helper function to calculate total for dummy data
export const calculateTotal = (data: WizardData): string => {
  const subtotal = data.items.reduce((total, item) => total + (item.price * item.quantity), 0);
  let rupiah = new Rupiah(subtotal);
  return rupiah.format;
};

export const calculateBalance = (data: WizardData): string => {
  const subtotal = data.items.reduce((total, item) => total + (item.price * item.quantity), 0);
  const balance = subtotal - data.downPayment;
  let rupiah = new Rupiah(balance);
  return rupiah.format; 
};

export const generatePDF = ({ data, calculateTotal, calculateBalance }: PDFGeneratorOptions) => {
  const doc = new jsPDF();
  // applyPlugin(jsPDF);

  var pageWidth = doc.internal.pageSize.getWidth();
  var margin = 20;
  var currentY = 45;

  // Helper function to add company header
  function addCompanyHeader() {
  var paidX = pageWidth / 2 + 30;
  var paidY = currentY - 40;
  var paidWidth = 40;
  var paidHeight = 35;
  
  var paidImageData = 'data:image/jpeg;base64,'
  

  // Try to add PAID image
  doc.addImage(paidImageData, 'jpeg', paidX, paidY, paidWidth, paidHeight);
 
    // Company name
  var headerWidth = pageWidth / 2 + 10;
  doc.setFontSize(12);
  doc.setFont('helvetica', 'bold');
  doc.text('PESONA BALI ROOM AND RESTAURANT', headerWidth, currentY, { align: 'left' });
  currentY += 5;
  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.text('JL SOEKARNO HATTA - LABUAN BAJO', headerWidth, currentY, { align: 'left' });

  currentY += 5;
  doc.setFontSize(10);
  doc.setFont('helvetica', 'bold');
  // Company address and contact
  var companyInfo = [
    'Phone : +62 821-4525-0266',
    'Email : hallpesona@gmail.com'
  ];
  
  for (var i = 0; i < companyInfo.length; i++) {
    doc.text(companyInfo[i], headerWidth, currentY, { align: 'left' });
    currentY += 5;
  }
  
  currentY += 5; // Extra space after header
}

// Helper function to add invoice box
function addInvoiceBox() {
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  var invoiceText = 'INVOICE';

  // Draw box around INVOICE text
  doc.text(invoiceText, pageWidth / 3 + 25, currentY , { align: 'left' });
  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.text(data.invoice, pageWidth / 3 + 25, currentY + 5, { align: 'left' });

  currentY += 10;
}

function addGuestDetails() {
  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  
  var tableWidth = pageWidth - (margin * 2);
  var col1Width = 25; // Width for labels
  var col2Width = tableWidth - col1Width; // Width for values
  var rowHeight = 5;
  const today = new Date();
  var serviceType = 'Room & Restaurant'
  if (data.serviceType === 'restaurant'){
      serviceType = 'Restaurant';
  }else if (data.serviceType === 'room'){
      serviceType = 'Room';
  }
  var guestData = [
    { label: 'Guest Name', value: data.customerName || '' },
    { label: 'Paid By', value: data.paymentMethod || 'Cash' },
    { label: 'Payment For', value: serviceType || '(Room, Restaurant, Room & Restaurant)' },
    { label: 'Arrival', value: data.arrival || today.toISOString().split('T')[0]},
    { label: 'Departure', value: data.departure || today.toISOString().split('T')[0]},
    { label: 'Cashier', value: data.cashierName || '' }
  ];
  
  // Draw table rows
  for (var i = 0; i < guestData.length; i++) {
    var row = guestData[i];
    
    // Add label (bold)
    doc.setFont('helvetica', 'bold');
    doc.text(row.label, margin + 2, currentY + 1);
    
    // Add value (normal)
    doc.setFont('helvetica', 'normal');
    doc.text(row.value, margin + col1Width + 5, currentY + 1);
    
    currentY += rowHeight;
  }
  
  currentY += 10;
}
function addItemsAutoTable() {
  // Prepare table data
  var tableData = [];
  
  // Add data rows
  for (var i = 0; i < data.items.length; i++) {
    var item = data.items[i];
    var orderDate = item.orderDate ? 
      new Date(item.orderDate).toLocaleDateString('id-ID') : '';
    
    tableData.push([
      orderDate,
      item.itemName,
      item.reference || '',
      item.quantity.toString(),
      'Rp.' + item.price.toLocaleString('id-ID'),
      'Rp.' + (item.price * item.quantity).toLocaleString('id-ID')
    ]);
  }
  

  tableData.push([
    'Total Amount',
    '',
       '',
    '',
    '',
    calculateTotal(data)
  ]);
  tableData.push([
    'Balance',
    '',
       '',
    '',
    '',
    calculateBalance(data)
  ]);
  let dp = new Rupiah(data.downPayment);
  tableData.push([
    'Down Payment',
    '',
    '',
    '',
    '',
   dp.format
  ]);


   autoTable(doc, {
    startY: currentY,
    head: [['Date', 'Description', 'Reference', 'QTY', 'Amount (IDR)', 'Total (IDR)']],
    body: tableData,
    theme: 'plain',
    styles: {
      fontSize: 8,
      cellPadding: 2,
      lineColor: [0, 0, 0],
      lineWidth: {
        top: 0,
        right: 0,
        bottom: 0, // No bottom border
        left: 0
      }
    },
    headStyles: {
      fillColor: [240, 240, 240],
      textColor: [0, 0, 0],
      fontStyle: 'bold',
      halign: 'center'
    },
    bodyStyles: {
      textColor: [0, 0, 0]
    },
      tableLineColor: [255, 255, 255], // White color to hide
  tableLineWidth: 0, // Or set to 0
    columnStyles: {
      0: { cellWidth: 20, halign: 'center' }, // Date
      1: { cellWidth: 70, halign: 'left' },   // Description
      2: { cellWidth: 25, halign: 'center' }, // Reference
      3: { cellWidth: 10, halign: 'center' }, // QTY
      4: { cellWidth: 25, halign: 'right' },  // Amount
      5: { cellWidth: 25, halign: 'right' }   // Total
    },
    // Style the last row (total) differently
    didParseCell: function(data: any) {
      if (data.row.index === tableData.length - 1) {
        data.cell.styles.fontStyle = 'bold';
        data.cell.styles.fillColor = [245, 245, 245];
         if (data.column.index === 0) {
          data.cell.colSpan = 5;
          data.cell.styles.halign = 'left';
        }
        // Right align the amount column
        if (data.column.index === 5) {
          data.cell.styles.halign = 'right';
        }
      }
      if (data.row.index === tableData.length - 2) {
        data.cell.styles.fontStyle = 'bold';
        data.cell.styles.fillColor = [245, 245, 245];
         if (data.column.index === 0) {
          data.cell.colSpan = 5;
          data.cell.styles.halign = 'left';
        }
        // Right align the amount column
        if (data.column.index === 5) {
          data.cell.styles.halign = 'right';
        }
      }
      if (data.row.index === tableData.length - 3) {
        data.cell.styles.fontStyle = 'bold';
        data.cell.styles.fillColor = [245, 245, 245];
        if (data.column.index === 0) {
          data.cell.colSpan = 5;
          data.cell.styles.halign = 'left';
        }
        // Right align the amount column
        if (data.column.index === 5) {
          data.cell.styles.halign = 'right';
        }
    }
    },
    margin: { left: margin, right: margin }
  });
  
  // Update currentY to position after table
  currentY = (doc as any).lastAutoTable.finalY + 20;
  doc.setFontSize(11);
  doc.setFont('helvetica', 'normal');
  doc.text('Thank you very much, we will always hope for your visit back to our place', pageWidth - margin - 170, currentY - 10);
  
}


// Helper function to add signature and PAID stamp
function addSignatureAndPaid() {
  var pageHeight = doc.internal.pageSize.getHeight();
  var signatureY = pageHeight - 40; // Position near bottom
  
  // Add signature on bottom right
  signatureY += 15;
  doc.setFont('helvetica', 'bold');
  doc.text(data.cashierName, pageWidth - margin - 60, signatureY+3);
  doc.text('PESONA BALI ROOM AND RESTAURANT', pageWidth - margin - 80, signatureY+10);
  

  // Add signature line
  signatureY += 5;
  doc.line(pageWidth - margin - 80, signatureY, pageWidth - margin - 10, signatureY);
  
  // Add PAID image instead of text
  var paidX = pageWidth - margin - 80;
  var paidY = signatureY - 40;
  var paidWidth = 60;
  var paidHeight = 30;
  
  var paidImageData = 'data:image/jpeg;base64,'

  try {
    // Try to add PAID image
    doc.addImage(paidImageData, 'jpeg', paidX, paidY, paidWidth, paidHeight);
  } catch (error) {
    // Fallback to text if image fails
    console.warn('Could not load PAID image, using text fallback');
    
    // Draw PAID box as fallback
    doc.setLineWidth(2);
    doc.rect(paidX, paidY, paidWidth, paidHeight);
    
    // Add PAID text as fallback
    doc.setFontSize(12);
    doc.setFont('helvetica', 'bold');
    doc.text('PAID', paidX + paidWidth/2, paidY + paidHeight/2 + 2, { align: 'center' });
    
    // Reset line width
    doc.setLineWidth(0.2);
  }
}
// Generate PDF sections
addCompanyHeader();
addInvoiceBox();
addGuestDetails();
addItemsAutoTable();
addSignatureAndPaid()
// Save the PDF
var timestamp = new Date().getTime();
doc.save('invoice-' + timestamp + '.pdf');

console.log('PDF generated successfully!');

  // Save the PDF
  doc.save(`invoice-${Date.now()}.pdf`);
};
